import java.util.Scanner;

public class I {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        int totalCount = input.nextInt();
        double rawInput = Double.parseDouble(input.next());
        long pVal = (long)(rawInput * 10000);
        run(totalCount, pVal);
    }

    public static void run(long total, long p) {
        long studiedCount = 0;
        long remaining = total;

        while (true) {
            long zeroCount = remaining * (remaining - 1) * (remaining - 2) / 6;
            long oneCount = studiedCount * remaining * (remaining - 1) / 2;
            long twoCount = studiedCount * (studiedCount - 1) * remaining / 2;
            long threeCount = studiedCount * (studiedCount - 1) * (studiedCount - 2) / 6;

            long weightedSum = zeroCount * 0 + oneCount * 1 + twoCount * 2 + threeCount * 2;
            long totalComb = total * (total - 1) * (total - 2) / 6;

            if (weightedSum * 5000 >= p * totalComb) {
                System.out.println(studiedCount);
                return;
            }
            studiedCount++;
            remaining--;
        }
    }
}
